// W38 SMC lead alert (owner), 18 Oct 2026: new SortMyCover leads + bookings -> one minimised message to Jono through EMMA
// /api/notify; watermark in static data, committed only after a 2xx. Run: node --test automation/tests/W38.test.mjs
// Logic: automation/lib/w38.mjs. Structure: automation/W38.json (generated by automation/build-w38.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { runCode, ifBranch, lvViolations, PG_CRED } from './_n8ncode.mjs';
import { checkSql, workflowSql } from './_sqlcheck.mjs';
import * as L from '../lib/w38.mjs';

const WF = JSON.parse(readFileSync(new URL('../W38.json', import.meta.url), 'utf8'));
const { senderKind, findUngated } = createRequire(import.meta.url)('../lib/egress-gate.cjs');
const START = 'Start tick (w38.start: gate + window)';
const READ = 'Read new SMC leads + bookings';
const PLAN = 'Plan alert (w38.plan)';
const SEND = 'Notify Jono (EMMA /api/notify)';
const GATE = `Live send? (${SEND})`;
const STUB = `Dry-run stub (${SEND})`;
const COMMIT = 'Commit or hold (w38.commit)';
const FAILING = 'Third failure in a row?';
const ON = { SMC_LEAD_ALERT_ENABLED: 'true' };
const T0 = '2026-10-18T09:00:00.000Z';
const at = (s) => new Date(Date.parse(T0) + s * 1000).toISOString();
const lead = (id, s, over = {}) => ({ kind: 'lead', id, created_at: at(s), first_name: 'Thandi', phone_last3: '234', origin: 'ctwa', ref: 'ad-new-bond', practice: 'SortMyCover test practice', ...over });
const booking = (id, s, over = {}) => ({ kind: 'booking', id, created_at: at(s), at: '2026-10-21T12:30:00+00:00', method: 'teams', status: 'booked', first_name: 'Thandi', phone_last3: '234', practice: 'SortMyCover test practice', ...over });
const node = (name) => WF.nodes.find((n) => n.name === name);
const out = (name, i = 0) => ((WF.connections[name] && WF.connections[name].main[i]) || []).map((t) => t.node);

test('the generated file is current; id, error workflow, lv-automation form, inactive, every minute', () => {
  const before = readFileSync(new URL('../W38.json', import.meta.url), 'utf8');
  execFileSync(process.execPath, [new URL('../build-w38.mjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')], { stdio: 'pipe' });
  assert.equal(readFileSync(new URL('../W38.json', import.meta.url), 'utf8'), before, 'W38.json is generated by build-w38.mjs');
  assert.deepEqual(lvViolations(WF, 'smc-w38'), []);
  assert.equal(WF.name, 'W38 SMC lead alert (owner)');
  assert.equal(WF.active, false);
  const trig = WF.nodes.filter((n) => n.type === 'n8n-nodes-base.scheduleTrigger');
  assert.deepEqual(trig.map((n) => n.parameters.rule.interval), [[{ field: 'minutes', minutesInterval: 1 }]]);
  const pg = WF.nodes.filter((n) => n.credentials);
  assert.deepEqual(pg.map((n) => [n.name, n.credentials.postgres]), [[READ, { id: '', name: PG_CRED }]], 'Postgres credential by name only, bound at import');
});

test('the query: columns exist in the migrations; email / full number / message text never leave the database', () => {
  assert.deepEqual(checkSql(workflowSql(WF)), []);
  const q = node(READ).parameters.query.replace(/--[^\n]*/g, '');
  assert.doesNotMatch(q, /email|\bbody\b|message|id_number|last_name|communications|conv_state/i);
  assert.equal(q.match(/l\.phone/g).length, q.match(/right\(regexp_replace\(coalesce\(l\.phone, ''\), '\[\^0-9\]', '', 'g'\), 3\)/g).length, 'the number only as its last 3 digits');
  assert.match(q, /l\.brand_id = \$1::uuid AND l\.created_at > nullif\(\$2, ''\)::timestamptz/);
  assert.match(q, /a\.brand_id = \$1::uuid AND a\.created_at > nullif\(\$2, ''\)::timestamptz/);
  assert.match(q, new RegExp(`LIMIT ${L.ROW_LIMIT}\\)`));
  assert.equal(node(READ).parameters.options.queryReplacement, '={{ [ $json.brand_id, $json.since ] }}');
});

test('send: POST https://emmadoesit.cloud/api/notify with x-emma-secret from env; body { message, source, title }', () => {
  const p = node(SEND).parameters;
  assert.equal(p.method, 'POST');
  assert.equal(p.url, 'https://emmadoesit.cloud/api/notify');
  assert.deepEqual(p.headerParameters.parameters, [{ name: 'content-type', value: 'application/json' }, { name: 'x-emma-secret', value: '={{ $env.EMMA_SHARED_SECRET }}' }]);
  assert.equal(p.jsonBody, '={{ JSON.stringify($json.request) }}');
  assert.equal(p.options.response.response.neverError, true, 'a 502 reaches Commit or hold as a status, not as a node error');
  assert.equal(node(SEND).onError, 'continueRegularOutput', 'no answer at all also reaches Commit or hold');
  assert.deepEqual(L.requestBody('x'), { message: 'x', source: 'smc-lead-alert', title: 'SortMyCover lead' });
  assert.equal(senderKind(node(SEND)), 'notify', 'egress-gate knows EMMA notify as a sender');
  assert.deepEqual(findUngated(WF), [], 'gated on DRY_RUN_SENDS');
});

test('wiring: plan -> DRY_RUN gate -> POST or stub -> commit -> third failure? -> stop (W22)', () => {
  assert.deepEqual(out('Every minute'), [START]);
  assert.deepEqual(out(START), [READ]);
  assert.deepEqual(out(READ), [PLAN]);
  assert.deepEqual(out(PLAN), [GATE]);
  assert.deepEqual([out(GATE, 0), out(GATE, 1)], [[SEND], [STUB]]);
  assert.deepEqual(out(SEND), [COMMIT]);
  assert.deepEqual(out(STUB), [COMMIT]);
  assert.deepEqual(out(COMMIT), [FAILING]);
  assert.deepEqual(out(FAILING, 0), ['Fail the run once (W22 emails ops)']);
  assert.equal(node('Fail the run once (W22 emails ops)').type, 'n8n-nodes-base.stopAndError');
  assert.equal(WF.settings.errorWorkflow, 'smc-w22');
});

test('formatter: first name, last 3 digits, source / angle, practice; never email, full number, ID number or message text', () => {
  const wide = lead('l1', 0, { first_name: 'Lerato Dlamini', phone: '+27 82 555 1234', phone_last3: undefined, email: 'lerato@gmail.com',
    id_number: '8001015009087', last_name: 'Dlamini', body: 'my salary is R40k, call me on 0825551234', message: 'hello', angle: 'new-bond' });
  const m = L.format([wide]);
  assert.equal(m, 'SortMyCover: 1 new lead\n- Lead: Lerato, WhatsApp ad (new-bond), phone ends 234, routed to SortMyCover test practice');
  assert.doesNotMatch(m, /lerato@|gmail|555|1234|8001015009087|Dlamini|salary|hello|@/);
  // a name field holding an email or a number is never echoed
  for (const v of ['lerato@gmail.com', '0825551234', '', null, '   ', '😀']) assert.match(L.line(lead('x', 0, { first_name: v })), /^- Lead: name not given yet,/);
  // public attribution values (ref / utm) are cleaned: no email-like token, no long digit runs
  const src = L.sourceText({ origin: 'page', ref: 'x lerato@gmail.com 0825551234 cycle1' });
  assert.equal(src, 'site (x cycle1)');
  assert.equal(L.sourceText({}), '');
  assert.equal(L.line(lead('x', 0, { practice: null, origin: null, ref: null, phone_last3: '' })), '- Lead: Thandi, no number, not routed');
  assert.equal(L.phoneTail('+27 82 555 1234'), '234');
  assert.equal(L.phoneTail('12'), '');
});

test('formatter: bookings in Africa/Johannesburg with the method; rebooking, held, repeat and test rows say so', () => {
  assert.equal(L.sastText('2026-10-21T12:30:00Z'), 'Wed 21 Oct 14:30 SAST');
  assert.equal(L.sastText('2026-12-31T22:15:00+00:00'), 'Fri 1 Jan 00:15 SAST');
  assert.equal(L.sastText(null), 'time not set');
  assert.equal(L.line(booking('b1', 0)), '- Booking: Thandi, Wed 21 Oct 14:30 SAST, Teams, phone ends 234, with SortMyCover test practice');
  assert.match(L.line(booking('b1', 0, { rebooked: true, method: 'whatsapp_call' })), /^- Rebooking: Thandi, .*, WhatsApp call,/);
  assert.match(L.line(booking('b1', 0, { status: 'pending_verification' })), /\(held until the email is verified\)$/);
  assert.match(L.line(lead('l1', 0, { repeat: true, synthetic: true })), /^- Repeat lead: .* \[test data\]$/);
  const m = L.format([lead('l1', 0), booking('b1', 1), lead('l2', 2)]);
  assert.match(m, /^SortMyCover: 2 new leads, 1 new booking\n/);
  assert.equal(m.split('\n').length, 4);
});

test('formatter: long ticks stay short (25 lines, "...and N more", under 3500 characters)', () => {
  const many = Array.from({ length: 40 }, (_, i) => lead(`l${i}`, i));
  const m = L.format(many);
  assert.equal(m.split('\n').length, 1 + 25 + 1);
  assert.match(m, /\n\.\.\.and 15 more \(see the CRM\)$/);
  const long = Array.from({ length: 25 }, (_, i) => lead(`l${i}`, i, { practice: 'P'.repeat(200) }));
  assert.ok(L.format(long).length <= L.MAX_CHARS);
});

test('first run: watermark = db_now, nothing sent, even when rows come back', () => {
  assert.deepEqual(L.start({}, ON), { run: true, brand_id: L.SMC_BRAND_ID, since: '' });
  const p = L.plan({}, [lead('l1', -10)], at(0));
  assert.equal(p.action, 'init');
  assert.equal(p.next.watermark, at(0));
  assert.equal(p.message, undefined);
  assert.ok('lead:l1' in p.next.seen, 'a row seen on the first run is history, never sent later');
});

test('watermark + de-dupe: overlap re-reads, seen ids are skipped, prune keeps the window and at most 200 ids', () => {
  const st = { watermark: at(0), seen: { 'lead:l1': Date.parse(at(-30)) } };
  assert.equal(L.start(st, ON).since, new Date(Date.parse(at(0)) - L.OVERLAP_MS).toISOString(), 'reads from watermark minus the overlap');
  const p = L.plan(st, [lead('l1', -30), lead('l2', -5), booking('b1', 20)], at(60));
  assert.equal(p.action, 'send');
  assert.deepEqual(p.keys, ['lead:l2', 'booking:b1'], 'l1 was sent before; oldest first');
  assert.equal(p.next.watermark, at(60));
  assert.deepEqual(Object.keys(p.next.seen).sort(), ['booking:b1', 'lead:l1', 'lead:l2']);
  assert.deepEqual(p.request, { message: p.message, source: 'smc-lead-alert', title: 'SortMyCover lead' });
  // nothing new -> idle, the watermark still advances
  const idle = L.plan({ ...st, ...p.next }, [lead('l2', -5), booking('b1', 20)], at(120));
  assert.equal(idle.action, 'idle');
  assert.equal(idle.next.watermark, at(120));
  // prune: ids older than the overlap window go; at most SEEN_CAP stay (newest)
  const now = Date.parse(at(0));
  assert.deepEqual(Object.keys(L.prune({ old: now - L.OVERLAP_MS - 120_000, keep: now - 1000 }, now)), ['keep']);
  const big = Object.fromEntries(Array.from({ length: 300 }, (_, i) => [`lead:${i}`, now - i]));
  const pr = L.prune(big, now);
  assert.equal(Object.keys(pr).length, L.SEEN_CAP);
  assert.ok('lead:0' in pr && !('lead:299' in pr));
  // a full page (ROW_LIMIT rows) advances only to its newest row; the watermark never moves back
  const page = Array.from({ length: L.ROW_LIMIT }, (_, i) => lead(`p${i}`, i));
  assert.equal(L.plan({ watermark: at(-1), seen: {} }, page, at(3600)).next.watermark, at(L.ROW_LIMIT - 1));
  assert.equal(L.plan({ watermark: at(500), seen: {} }, [lead('z', 10)], at(400)).next.watermark, at(500));
  assert.equal(L.plan({ watermark: at(0) }, JSON.stringify([lead('s', 1)]), at(5)).items, 1, 'jsonb as text is parsed too');
  assert.throws(() => L.plan({ watermark: at(0) }, [], undefined), /db_now/);
});

test('retry: a non-2xx or no answer keeps the old watermark, the next tick resends; the 3rd failure in a row alerts once', () => {
  const st0 = { watermark: at(0), seen: {} };
  const p1 = L.plan(st0, [lead('l1', 10)], at(60));
  const f1 = L.commit(st0, p1, { statusCode: 502, body: { delivered: false } }, at(61));
  assert.deepEqual([f1.delivered, f1.alert, f1.state.watermark, f1.state.fails], [false, false, at(0), 1]);
  assert.deepEqual(f1.state.seen, {}, 'the unsent item is not marked seen');
  const p2 = L.plan(f1.state, [lead('l1', 10), lead('l2', 70)], at(120));
  assert.deepEqual(p2.keys, ['lead:l1', 'lead:l2'], 'the failed item goes again, with the new one');
  const f2 = L.commit(f1.state, p2, { error: { message: 'ETIMEDOUT' } }, at(121));
  assert.deepEqual([f2.state.fails, f2.alert, f2.state.last_error.detail], [2, false, 'ETIMEDOUT']);
  const f3 = L.commit(f2.state, p2, { statusCode: 401, body: { result: 'Unauthorised' } }, at(181));
  assert.deepEqual([f3.state.fails, f3.alert], [3, true]);
  assert.equal(L.commit(f3.state, p2, { statusCode: 502 }, at(241)).alert, false, 'the run fails once per outage, not every minute');
  const ok = L.commit(f3.state, p2, { statusCode: 200, body: { delivered: true } }, at(242));
  assert.deepEqual([ok.delivered, ok.state.watermark, ok.state.fails, ok.state.last.items], [true, at(120), 0, 2]);
  assert.ok('lead:l1' in ok.state.seen && 'lead:l2' in ok.state.seen);
  assert.equal(ok.state.last_error, undefined);
});

test('gates: SMC_LEAD_ALERT_ENABLED must be exactly "true"; off drops the state (no replay when switched on again)', async () => {
  for (const v of [undefined, '', 'false', 'TRUE', '1']) {
    assert.equal(L.start({ watermark: at(0) }, { SMC_LEAD_ALERT_ENABLED: v }).run, false);
    const sd = { watermark: at(0), seen: { 'lead:x': 1 }, fails: 2 };
    assert.deepEqual(await runCode(WF, START, { env: { SMC_LEAD_ALERT_ENABLED: v }, staticData: sd }), []);
    assert.deepEqual(sd, {}, 'state dropped');
  }
  const sd = {};
  assert.deepEqual(await runCode(WF, START, { env: ON, staticData: sd }), [{ json: { brand_id: L.SMC_BRAND_ID, since: '' } }]);
  assert.deepEqual(L.gates({ DRY_RUN_SENDS: 'true', SMC_LEAD_ALERT_ENABLED: 'true' }), { enabled: true, dryRun: true });
});

test('gates: DRY_RUN_SENDS=true takes the stub (no POST), logs the message and still advances the watermark', async () => {
  const p = L.plan({ watermark: at(0), seen: {} }, [lead('l1', 10)], at(60));
  assert.equal(ifBranch(WF, GATE, { json: p, env: { DRY_RUN_SENDS: 'true' } }), false, 'dry run -> stub');
  assert.equal(ifBranch(WF, GATE, { json: p, env: {} }), true, 'live -> POST');
  const stubbed = await runCode(WF, STUB, { items: [p] });
  assert.equal(stubbed[0].json.dry_run, true);
  const sd = { watermark: at(0), seen: {} };
  const logged = [];
  const log = console.log; console.log = (s) => logged.push(String(s));
  try {
    const r = await runCode(WF, COMMIT, { items: [stubbed[0].json], staticData: sd, refs: { [PLAN]: p } });
    assert.deepEqual(r[0].json, { delivered: false, dry_run: true, status: 200, items: 1, fails: 0, alert: false });
  } finally { console.log = log; }
  assert.match(logged.join('\n'), /DRY_RUN_SENDS=true: logged, not sent[\s\S]*- Lead: Thandi/);
  assert.equal(sd.watermark, at(60));
  assert.equal(sd.last.message, p.message);
});

test('the real nodes across ticks: first run silent, a 502 holds, the retry sends everything once, then quiet', async () => {
  const sd = {};
  const tick = async (rows, dbNow, answer) => {
    const s = await runCode(WF, START, { env: ON, staticData: sd });
    if (!s.length) return { stopped: 'start' };
    const planned = await runCode(WF, PLAN, { items: [{ db_now: dbNow, items: rows }], staticData: sd });
    if (!planned.length) return { stopped: 'plan', since: s[0].json.since };
    const p = planned[0].json;
    assert.equal(ifBranch(WF, GATE, { json: p, env: {} }), true);
    const c = await runCode(WF, COMMIT, { items: [answer], staticData: sd, refs: { [PLAN]: p } });
    return { since: s[0].json.since, message: p.message, commit: c[0].json, failing: ifBranch(WF, FAILING, { json: c[0].json }) };
  };
  assert.deepEqual(await tick([], at(0), null), { stopped: 'plan', since: '' }, 'first run: no rows read, nothing sent');
  assert.equal(sd.watermark, at(0));
  const t2 = await tick([lead('l1', 30)], at(60), { statusCode: 502, body: { delivered: false } });
  assert.match(t2.message, /^SortMyCover: 1 new lead\n- Lead: Thandi/);
  assert.deepEqual([t2.commit.delivered, t2.commit.fails, t2.failing, sd.watermark], [false, 1, false, at(0)]);
  const t3 = await tick([lead('l1', 30), booking('b1', 90)], at(120), { statusCode: 200, body: { delivered: true } });
  assert.equal(t3.since, new Date(Date.parse(at(0)) - L.OVERLAP_MS).toISOString(), 'the window still starts at the held watermark');
  assert.match(t3.message, /^SortMyCover: 1 new lead, 1 new booking\n- Lead: Thandi.*\n- Booking: Thandi/);
  assert.deepEqual([t3.commit.delivered, t3.commit.fails, sd.watermark], [true, 0, at(120)]);
  assert.deepEqual(await tick([lead('l1', 30), booking('b1', 90)], at(180), null), { stopped: 'plan', since: new Date(Date.parse(at(120)) - L.OVERLAP_MS).toISOString() }, 'the overlap re-read sends nothing twice');
  assert.equal(sd.watermark, at(180));
  // three failures in a row -> the IF to "Fail the run once" is true exactly once
  const fails = [];
  for (let i = 0; i < 4; i++) fails.push((await tick([lead('l9', 200)], at(240 + i * 60), { statusCode: 502 })).failing);
  assert.deepEqual(fails, [false, false, true, false]);
});
